#!/usr/bin/env bash
#
# gen-ts-types.sh — Generate TypeScript type declarations for shared Soroban
# contract types from committed spec XDR snapshots.
#
# This script reads the committed contract spec XDR snapshots under
# `lifebank-soroban/specs/` and emits TypeScript type declarations into
# `backend/src/__contracts__/generated.ts`. The generated file is the single
# source of truth shared by the NestJS backend, the `contract-event-indexer`,
# and the `__contracts__` module — replacing hand-redeclared shapes.
#
# Usage:
#   ./scripts/gen-ts-types.sh            # generate the TS file
#   ./scripts/gen-ts-types.sh --check    # fail if committed file is stale
#
# The generated file is marked as generated; do not edit it by hand.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SOROBAN_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
REPO_ROOT="$(cd "${SOROBAN_ROOT}/.." && pwd)"

SPECS_DIR="${SOROBAN_ROOT}/specs"
OUTPUT_FILE="${REPO_ROOT}/backend/src/__contracts__/generated.ts"

CHECK_MODE=0
if [[ "${1:-}" == "--check" ]]; then
  CHECK_MODE=1
fi

if [[ ! -d "${SPECS_DIR}" ]]; then
  echo "error: spec snapshots directory not found: ${SPECS_DIR}" >&2
  echo "       run scripts/build-all.sh and commit the spec snapshots first." >&2
  exit 1
fi

# Collect spec snapshot files (XDR). Sorted for deterministic output.
mapfile -t SPEC_FILES < <(find "${SPECS_DIR}" -maxdepth 1 -type f -name '*.xdr' | sort)

if [[ ${#SPEC_FILES[@]} -eq 0 ]]; then
  echo "error: no spec XDR snapshots found in ${SPECS_DIR}" >&2
  exit 1
fi

# Generate into a temp file first so we can diff for --check mode.
TMP_OUT="$(mktemp)"
trap 'rm -f "${TMP_OUT}"' EXIT

{
  echo "// AUTO-GENERATED FILE — DO NOT EDIT BY HAND."
  echo "//"
  echo "// Generated by lifebank-soroban/scripts/gen-ts-types.sh from the committed"
  echo "// contract spec XDR snapshots in lifebank-soroban/specs/."
  echo "//"
  echo "// To regenerate:"
  echo "//   cd lifebank-soroban && ./scripts/gen-ts-types.sh"
  echo "//"
  echo "// This file is the single source of truth for shared contract types across"
  echo "// the NestJS backend, the contract-event-indexer, and the __contracts__ module."
  echo ""
  echo "/* eslint-disable */"
  echo "/* tslint:disable */"
  echo ""

  for spec in "${SPEC_FILES[@]}"; do
    contract_name="$(basename "${spec}" .xdr)"
    echo "// ---------------------------------------------------------------------------"
    echo "// Contract: ${contract_name}"
    echo "// Source:   lifebank-soroban/specs/$(basename "${spec}")"
    echo "// ---------------------------------------------------------------------------"
    echo ""

    # Extract the contract spec and emit TypeScript declarations.
    # `stellar contract inspect` reads the spec XDR and prints a JSON spec
    # describing the contract's functions and types. We transform that JSON
    # into TypeScript type declarations.
    if ! command -v stellar >/dev/null 2>&1; then
      echo "error: 'stellar' CLI not found; required to inspect spec XDR" >&2
      exit 1
    fi

    spec_json="$(stellar contract inspect --xdr-file "${spec}" --output json 2>/dev/null || true)"
    if [[ -z "${spec_json}" ]]; then
      echo "error: failed to inspect spec XDR: ${spec}" >&2
      exit 1
    fi

    # Delegate JSON -> TypeScript transformation to a small Node script so the
    # transformation logic is testable and maintainable.
    node "${SCRIPT_DIR}/spec-xdr-to-ts.js" "${contract_name}" <<<"${spec_json}"
    echo ""
  done
} >"${TMP_OUT}"

if [[ ${CHECK_MODE} -eq 1 ]]; then
  if [[ ! -f "${OUTPUT_FILE}" ]]; then
    echo "error: generated file is missing: ${OUTPUT_FILE}" >&2
    echo "       run ./scripts/gen-ts-types.sh and commit the result." >&2
    exit 1
  fi
  if ! diff -u "${OUTPUT_FILE}" "${TMP_OUT}" >/dev/null 2>&1; then
    echo "error: generated TypeScript contract types are stale." >&2
    echo "       The committed file does not match the contract spec snapshots." >&2
    echo "       run ./scripts/gen-ts-types.sh and commit the result." >&2
    echo "" >&2
    diff -u "${OUTPUT_FILE}" "${TMP_OUT}" >&2 || true
    exit 1
  fi
  echo "ok: generated TypeScript contract types are up to date."
  exit 0
fi

mkdir -p "$(dirname "${OUTPUT_FILE}")"
cp "${TMP_OUT}" "${OUTPUT_FILE}"
echo "generated: ${OUTPUT_FILE}"